const disableAll = [];
function selectArgs(table, disableAll) {
  const labels = location.hostname.toLowerCase().split(".");
  const hosts = [];
  for (let i = 0; i < labels.length; i++) {
    hosts.push(labels.slice(i).join("."));
    // entity forms: "a.b.site.co.uk" also matches "site.*" (suffix of one or two labels)
    for (let r = 1; r <= 2; r++) if (labels.length - i > r) hosts.push(labels.slice(i, labels.length - r).join(".") + ".*");
  }
  if (hosts.some((h) => disableAll.includes(h))) return [];
  const excluded = new Set();
  for (const h of hosts) for (const i of table.exclude[h] || []) excluded.add(i);
  const chosen = new Set();
  for (const h of hosts) for (const i of table.include[h] || []) if (!excluded.has(i)) chosen.add(i);
  return [...chosen].map((i) => table.args[i]);
}


function setConstant(chain, rawValue) {
  if (!chain) return;
  const values = {
    undefined: undefined,
    false: false,
    true: true,
    null: null,
    "": "",
    "''": "",
    noopFunc: function () {},
    trueFunc: () => true,
    falseFunc: () => false,
    emptyArr: () => [],
    emptyObj: () => ({}),
    "[]": () => [],
    "{}": () => ({}),
  };
  let value;
  if (Object.prototype.hasOwnProperty.call(values, rawValue)) {
    value = values[rawValue];
    if (rawValue === "emptyArr" || rawValue === "[]") value = [];
    if (rawValue === "emptyObj" || rawValue === "{}") value = {};
  } else if (/^-?\d+$/.test(rawValue) && Math.abs(Number(rawValue)) <= 0x7fff) {
    value = Number(rawValue);
  } else {
    return; // unsupported value
  }

  const trapProp = (owner, prop) => {
    const desc = Object.getOwnPropertyDescriptor(owner, prop);
    if (desc && desc.configurable === false) return;
    try {
      Object.defineProperty(owner, prop, {
        configurable: true,
        enumerable: desc ? desc.enumerable : true,
        get: () => value,
        set: () => {},
      });
    } catch {}
  };

  const trapChain = (owner, chain) => {
    const pos = chain.indexOf(".");
    if (pos === -1) {
      trapProp(owner, chain);
      return;
    }
    const prop = chain.slice(0, pos);
    const rest = chain.slice(pos + 1);
    let current = owner[prop];
    if (current !== null && (typeof current === "object" || typeof current === "function")) {
      trapChain(current, rest);
      return;
    }
    const desc = Object.getOwnPropertyDescriptor(owner, prop);
    if (desc && desc.configurable === false) return;
    if (desc && desc.get) {
      // Already trapped (e.g. by another set filter on the same object): chain onto it.
      const oldGet = desc.get;
      const oldSet = desc.set;
      try {
        Object.defineProperty(owner, prop, {
          configurable: true,
          enumerable: desc.enumerable,
          get: oldGet,
          set(v) {
            if (oldSet) oldSet.call(this, v);
            const cur = oldGet.call(this);
            if (cur !== null && (typeof cur === "object" || typeof cur === "function")) trapChain(cur, rest);
          },
        });
      } catch {}
      return;
    }
    try {
      Object.defineProperty(owner, prop, {
        configurable: true,
        enumerable: true,
        get: () => current,
        set: (v) => {
          current = v;
          if (v !== null && (typeof v === "object" || typeof v === "function")) trapChain(v, rest);
        },
      });
    } catch {}
  };

  trapChain(window, chain);
}

for (const args of selectArgs(table, disableAll)) {
  try { setConstant(...args); } catch (e) { /* a broken filter must not break the page */ }
}
